# Sequences

    import Animator as Anim
    import Html

    Anim.div
        (Anim.keyframes
            [ Anim.loop
                [ Anim.set [ Anim.opacity 1 ]
                , Anim.wait (Anim.ms 200)
                , Anim.step (Anim.ms 200) [ Anim.opacity 0 ]
                ]
            ]
        )
        []
        [ Html.text "Hello!" ]

